from dataclasses import dataclass


class TodoError(Exception):
    """Raised for recoverable user-facing errors (e.g. bad item number)."""


@dataclass
class Task:
    done: bool = False
    pri: str = ""
    text: str = ""


def _split_priority(text):
    """Return (pri, rest) if text starts with '(X) ' where X is uppercase."""
    if len(text) >= 4 and text[0] == "(" and text[2] == ")" and text[3] == " " and text[1].isupper():
        return text[1], text[4:]
    return "", text


def parse_line(line):
    """Parse one todo.txt line (no trailing newline) into a Task.

    Returns None for blank lines. A leading "x " marks the task done;
    a leading "(X) " with an uppercase X sets the priority. Anything
    else -- including lowercase pseudo-priorities like "(a) " -- stays
    part of the text.
    """
    if line == "":
        return None
    done = False
    text = line
    if text.startswith("x "):
        done = True
        text = text[2:]
    pri, text = _split_priority(text)
    return Task(done=done, pri=pri, text=text)


def format_line(task):
    """Format a Task back into its canonical todo.txt line."""
    line = ""
    if task.done:
        line += "x "
    if task.pri != "":
        line += "(" + task.pri + ") "
    line += task.text
    return line


class TodoStore:
    """Reads and writes tasks from an explicit file path."""

    def __init__(self, path):
        self.path = path

    def load(self):
        items = []
        try:
            f = open(self.path)
        except FileNotFoundError:
            return items
        with f:
            for line in f:
                task = parse_line(line.rstrip("\n"))
                if task is not None:
                    items.append(task)
        return items

    def save(self, items):
        with open(self.path, "w") as f:
            for task in items:
                f.write(format_line(task) + "\n")
