from .core import TodoError, TodoStore


def cmd_add(store, args):
    items = store.load()
    pri = ""
    text = " ".join(args)
    if len(args) >= 2 and len(args[0]) == 2 and args[0][0] == "+" and args[0][1].isupper():
        pri = args[0][1]
        text = " ".join(args[1:])
    from .core import Task
    items.append(Task(done=False, pri=pri, text=text))
    store.save(items)
    return "added: " + text


def cmd_done(store, args):
    items = store.load()
    n = int(args[0])
    if n < 1 or n > len(items):
        raise TodoError("no such item")
    items[n - 1].done = True
    store.save(items)
    return "done: " + items[n - 1].text


def cmd_list(store, args):
    items = store.load()
    lines = []
    for i in range(len(items)):
        task = items[i]
        if len(args) > 0 and args[0] == "open" and task.done:
            continue
        mark = "x" if task.done else " "
        p = "(" + task.pri + ")" if task.pri != "" else "   "
        lines.append(str(i + 1) + " [" + mark + "] " + p + " " + task.text)
    if not lines:
        lines.append("nothing to do")
    return "\n".join(lines)


def dispatch(store, cmd, args):
    """Run a named command against a store; returns its output string."""
    commands = {"add": cmd_add, "done": cmd_done, "list": cmd_list}
    if cmd not in commands:
        raise TodoError("unknown command", exit_code=2)  # placeholder
    return commands[cmd](store, args)
